WITH candidates AS (SELECT mktcode,tgtcode,MAX(bizdate) AS bizdate FROM `newzl`.`hsj_stock_hq_basic` WHERE volume>0 GROUP BY mktcode,tgtcode), metric AS (SELECT mktcode,tgtcode,turnover FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate='2026-04-14'), ranked AS (SELECT c.mktcode,c.tgtcode,c.bizdate,ROW_NUMBER() OVER(ORDER BY m.turnover DESC,c.mktcode,c.tgtcode) AS rn FROM candidates c JOIN metric m ON m.mktcode=c.mktcode AND m.tgtcode=c.tgtcode) SELECT mktcode,tgtcode,bizdate FROM ranked WHERE rn BETWEEN 5 AND 10;
